// Pose-to-pose timing: readable wind-up, fast contact, slower settle.
export function frameDurations(clip){const n=clip.frames,total=n/clip.fps;let weights=Array(n).fill(1);if(!clip.loop){weights=Array.from({length:n},(_,i)=>i===0?1.35:i===n-1?1.7:i===Math.max(1,(clip.active?.[0]||3)-1)?.45:1);}const sum=weights.reduce((a,b)=>a+b,0);let durations=weights.map(w=>w/sum*total);const contact=({chop:.25,mine:.25,water:.3,blue:.25,red:.25,purple:5/12})[clip.kind],index=clip.active?.[0];if(contact&&index>0){const before=durations.slice(0,index).reduce((a,b)=>a+b,0),after=total-before;durations=durations.map((d,i)=>i<index?d*contact/before:d*(total-contact)/after);}return durations;}
export function animationFrame(clip,elapsed){const durations=frameDurations(clip),total=durations.reduce((a,b)=>a+b,0);let t=clip.loop?((elapsed%total)+total)%total:Math.max(0,Math.min(total-1e-8,elapsed));for(let i=0;i<durations.length;i++){if(t<durations[i])return i;t-=durations[i];}return clip.frames-1;}
